displayContent.text:
class Client {
…

	#record(dir: Logged["dir"], frame: Frame, issues?: string[]): Logged {
		const entry: Logged = { i: this.log.length, t: Date.now() - this.#t0, dir, frame, ...(issues?.length ? { issues } : {}) };
		this.log.push(entry);
		for (const w of [...this.#waiters]) {
			if (w.pred(entry)) {
				this.#waiters.splice(this.#waiters.indexOf(w), 1);
				w.resolve(entry);
			}
		}
		return entry;
	}

	#onFrame(frame: Frame): void {
		let issues: string[] = [];
		if (typeof frame.method === "string") {
			if (frame.method.startsWith("fs/") || frame.method.startsWith("terminal/")) this.violations.push(`client call ${frame.method}`);
			if (this.v2) issues = validateAcpV2Frame("id" in frame ? "request" : "notification", frame.method, frame.params);
			this.#record("←agent", frame, issues);
			if ("id" in frame) this.#answer(frame);
			return;
		}
		const pending = this.#pending.get(frame.id as number);
		if (this.v2 && pending && !frame.error) issues = validateAcpV2Frame("response", pending.method, frame.result);
		const entry = this.#record("←agent", frame, issues);
		if (pending) {
			this.#pending.delete(frame.id as number);
			pending.resolve({ ...frame, i: entry.i });
		}
		if (issues.length) this.violations.push(`schema ${pending?.method}: ${issues.join("; ")}`);
	}

	#answer(frame: Frame): void {
		if (frame.method === "session/request_permission") {
			const option = frame.params.options.find((o: any) => o.kind === "allow_once") ?? frame.params.options[0];
			this.#send({ jsonrpc: "2.0", id: frame.id, result: { outcome: { outcome: "selected", optionId: option.optionId } } });
			return;
		}
		this.#send({ jsonrpc: "2.0", id: frame.id, error: { code: -32601, message: "not supported by QA client" } });
	}

	#send(frame: Frame): void {
		this.#record("→agent", frame);
		(this.#proc.stdin as import("bun").FileSink).write(`${JSON.stringify(frame)}\n`);
	}

	request(method: string, params: unknown): Promise<Reply> {
		const id = this.#next++;
		const done = Promise.withResolvers<Reply>();
		this.#pending.set(id, { method, resolve: done.resolve });
		this.#send({ jsonrpc: "2.0", id, method, params });
		return done.promise;
	}

	notify(method: string, params: unknown): void {
		this.#send({ jsonrpc: "2.0", method, params });
	}

	waitFor(pred: (l: Logged) => boolean, timeoutMs: number, label: string): Promise<Logged> {
		const hit = this.log.find(pred);
		if (hit) return Promise.resolve(hit);
		const done = Promise.withResolvers<Logged>();
		this.#waiters.push({ pred, resolve: done.resolve });
		const timer = setTimeout(() => done.reject(new Error(`timeout waiting for ${label}`)), timeoutMs);
		return done.promise.finally(() => clearTimeout(timer));
	}

	updates(kind?: string): Logged[] {
		return this.log.filter(
			l => l.dir === "←agent" && l.frame.method === "session/update" && (!kind || l.frame.params?.update?.sessionUpdate === kind),
		);
	}

	states(): Array<{ i: number; state: string; stopReason?: string }> {
		return this.updates("state_update").map(l => ({ i: l.i, state: l.frame.params.update.state, stopReason: l.frame.params.update.stopReason }));
	}

	async close(): Promise<void> {
		(this.#proc.stdin as import("bun").FileSink).end();
		const exited = await Promise.race([this.#proc.exited, Bun.sleep(8000).then(() => "timeout")]);
		if (exited === "timeout") this.#proc.kill();
	}
}

const idleAfter = (after: number) => (l: Logged) =>
	l.i > after && l.frame.method === "session/update" && l.frame.params?.update?.sessionUpdate === "state_update" && l.frame.params.update.state === "idle";
const text = (s: string) => [{ type: "text", text: s }];

async function main(): Promise<void> {
	const [scenario, outDir] = process.argv.slice(2);
	if (!scenario || !outDir) throw new Error("usage: run.ts <scenario> <outDir>");
	await fs.mkdir(outDir, { recursive: true });
	const v2 = scenario !== "v1-flag-off";
	const cfg = path.join(outDir, `${scenario}.config.yml`);
	await Bun.write(cfg, `acp:\n  protocolV2: ${v2}\n`);
	const project = path.join(os.tmpdir(), "acp-v2-qa-project");
	await fs.mkdir(project, { recursive: true });
	const c = new Client(cfg, project, v2);
	const checks: Array<{ check: string; ok: boolean; detail?: unknown }> = [];
	const check = (name: string, ok: boolean, detail?: unknown) => checks.push({ check: name, ok, ...(detail === undefined ? {} : { detail }) });
	const sessionFile = path.join(outDir, "v2-ack.session.json");
	try {
		const init = await c.request("initialize", { protocolVersion: 2, clientCapabilities: {}, info: { name: "qa", version: "1" } });
		check("initialize protocolVersion", init.result?.protocolVersion === (v2 ? 2 : 1), init.result?.protocolVersion);
		if (scenario === "v2-resume") {
			const { sessionId, userIds } = await Bun.file(sessionFile).json();
			const before = c.log.length;
			const resumed = await c.request("session/resume", { sessionId, cwd: project, replayFrom: { type: "start" } });
			const replayIds = c.updates("user_message").filter(l => l.i > before && l.i < resumed.i).map(l => l.frame.params.update.messageId);
			check("replayed user ids equal live ids", JSON.stringify(replayIds) === JSON.stringify(userIds), { replayIds, userIds });
			const snap = c.states().filter(s => s.i > before && s.i < resumed.i);
			check("state snapshot before resume response", snap.length > 0 && snap.at(-1)!.i < resumed.i, snap);
			await c.close();
			const c2 = new Client(cfg, project, v2);
			await c2.request("initialize", { protocolVersion: 2, clientCapabilities: {}, info: { name: "qa", version: "1" } });
			const b2 = c2.log.length;
			const r2 = await c2.request("session/resume", { sessionId, cwd: project });
			const noCursorUsers = c2.updates("user_message").filter(l => l.i > b2 && l.i < r2.i).length;
			const noCursorStates = c2.states().filter(s => s.i > b2 && s.i < r2.i);
			check("no cursor: no replay, only snapshot", noCursorUsers === 0 && noCursorStates.length === 1, { noCursorUsers, noCursorStates });
			const bad = await c2.request("session/resume", { sessionId, cwd: project, replayFrom: { type: "_custom" } });
			check("unknown cursor → -32602", bad.error?.code === -32602, bad.error);
			c.violations.push(...c2.violations);
			c.log = [...c.log, ...c2.log];
			await c2.close();
		} else {
			const created = await c.request("session/new", { cwd: project, mcpServers: [] });
			const sessionId = created.result.sessionId as string;
			check("session/new has no modes on v2 / modes on v1", v2 ? !("modes" in created.result) && Array.isArray(created.result.availableCommands) : "modes" in created.result);
			if (scenario === "v2-ack" || scenario === "v1-flag-off") {
				const before = c.log.length;
				const resp = await c.request("session/prompt", { sessionId, prompt: text("Reply with a short poem about rivers, four lines.") });
				if (v2) {
					const messageId = resp.result?.messageId;
					check("prompt response carries messageId", typeof messageId === "string", resp.result);
					const idle = await c.waitFor(idleAfter(before), 90_000, "idle");
					check("response precedes idle (ack before turn end)", resp.i < idle.i, { response: resp.i, idle: idle.i });
					const echo = c.updates("user_message").find(l => l.i > before);
					check("user_message echo after response with same id", !!echo && echo.i > resp.i && echo.frame.params.update.messageId === messageId, echo?.frame.params.update);
					const chunks = c.updates("agent_message_chunk").filter(l => l.i > before);
					check("agent chunks carry messageId", chunks.length > 0 && chunks.every(l => typeof l.frame.params.update.messageId === "string"), chunks.length);
					const states = c.states().filter(s => s.i > before);
					check("running first, idle(end_turn) last", states[0]?.state === "running" && states.at(-1)?.stopReason === "end_turn", states);
					const second = await c.request("session/prompt", { sessionId, prompt: text("Now one line only: say ok.") });
					await c.waitFor(idleAfter(second.i), 90_000, "idle 2");
					await Bun.write(sessionFile, JSON.stringify({ sessionId, userIds: [messageId, second.result?.messageId] }));
				} else {
					const chunks = c.log.filter(l => l.i > before && l.frame.method === "session/update" && l.frame.params?.update?.sessionUpdate === "agent_message_chunk");
					check("v1 prompt resolves at turn end (after all chunks)", chunks.length > 0 && chunks.every(l => l.i < resp.i) && resp.result?.stopReason === "end_turn", { chunks: chunks.length, resp: resp.result });
					check("v1 has no state_update", c.updates("state_update").length === 0);
				}
			} else if (scenario === "v2-wake" || scenario === "v2-wake-task") {
				const before = c.log.length;
				const instruction =
					scenario === "v2-wake"
						? "Start a background job with the bash tool (set async: true) running exactly `sleep 6 && echo wake-done`. Do not wait for it; reply only 'started' and end your turn."
						: "Use the task tool to spawn exactly one subagent (agent: sonic) whose task is: 'Run `sleep 5` with bash, then reply with the word pong.' Do not wait for its result; reply only 'spawned' and end your turn.";
				const resp = await c.request("session/prompt", { sessionId, prompt: text(instruction) });
				check("prompt acknowledged", typeof resp.result?.messageId === "string", resp.result ?? resp.error);
				const firstIdle = await c.waitFor(idleAfter(before), 90_000, "first idle");
				const wakeRunning = await c.waitFor(
					l => l.i > firstIdle.i && l.frame.params?.update?.sessionUpdate === "state_update" && l.frame.params.update.state === "running",
					90_000,
					"wake running",
				);
				const wakeIdle = await c.waitFor(idleAfter(wakeRunning.i), 90_000, "wake idle");
				const between = c.log.filter(l => l.i > firstIdle.i && l.i < wakeRunning.i && l.frame.params?.update?.sessionUpdate === "agent_message_chunk");
				check("no wake content before its running", between.length === 0, between.length);
				const wakeChunks = c.updates().filter(l => l.i > wakeRunning.i && l.i < wakeIdle.i);
				check("wake: running → updates → idle with no prompt open", wakeChunks.length > 0, { running: wakeRunning.i, idle: wakeIdle.i, stopReason: wakeIdle.frame.params.update.stopReason, updates: wakeChunks.length });
			} else if (scenario === "v2-cancel") {
				const before = c.log.length;
				const resp = c.request("session/prompt", { sessionId, prompt: text("Count from 1 to 400, one number per line, no other text.") });
				await c.waitFor(l => l.i > before && l.frame.params?.update?.sessionUpdate === "agent_message_chunk", 90_000, "first chunk");
				c.notify("session/cancel", { sessionId });
				const r = await resp;
				check("prompt answered (inserted before cancel → success)", !!r.result || r.error?.code === -32800, r.result ?? r.error);
				const idle = await c.waitFor(idleAfter(before), 30_000, "cancel idle");
				check("idle(cancelled)", idle.frame.params.update.stopReason === "cancelled", idle.frame.params.update);
				await Bun.sleep(1500);
				const after = c.log.filter(l => l.i > idle.i && l.dir === "←agent" && l.frame.params?.update?.sessionUpdate !== "usage_update");
				check("idle(cancelled) is the last content frame", after.every(l => l.frame.params?.update?.sessionUpdate !== "agent_message_chunk"), after.map(l => l.frame.params?.update?.sessionUpdate ?? l.frame.method));
			}
		}
	} catch (error) {
		check("scenario completed", false, String(error));
	} finally {
		await c.close();
	}
	check("no fs/terminal client calls and no schema issues", c.violations.length === 0, c.violations);
	const pass = checks.every(x => x.ok);
	const out = { scenario, model: MODEL, pass, checks, frames: c.log };
	await Bun.write(path.join(outDir, `${scenario}.json`), JSON.stringify(out, null, 1));
	console.log(`${scenario}: ${pass ? "PASS" : "FAIL"}`);
	for (const x of checks) console.log(`  ${x.ok ? "ok  " : "FAIL"} ${x.check}${x.ok ? "" : ` ${JSON.stringify(x.detail)?.slice(0, 400)}`}`);
	process.exit(pass ? 0 : 1);
}

await main();

