	console.log(Date.now() - t0, "→", JSON.stringify(f).slice(0, 200));
	sink.write(`${JSON.stringify(f)}\n`);
};
const pending = new Map<number, (f: any) => void>();
(async () => {
	const dec = new TextDecoder();
	let buf = "";
	for await (const chunk of proc.stdout as ReadableStream<Uint8Array>) {
		buf += dec.decode(chunk, { stream: true });
		let nl: number;
		while ((nl = buf.indexOf("\n")) >= 0) {
			const line = buf.slice(0, nl);
			buf = buf.slice(nl + 1);
			if (!line.trim()) continue;
			const f = JSON.parse(line);
			const u = f.params?.update;
			console.log(Date.now() - t0, "←", f.method ?? `resp ${f.id}`, u ? `${u.sessionUpdate} ${u.state ?? ""} ${u.stopReason ?? ""}` : JSON.stringify(f.result ?? f.error ?? "").slice(0, 160));
			if (f.id !== undefined && !f.method) pending.get(f.id)?.(f);
		}
	}
})();
(async () => {
	for await (const chunk of proc.stderr as ReadableStream<Uint8Array>) process.stderr.write(chunk);
})();
let id = 0;
const req = (method: string, params: unknown) => {
	const p = Promise.withResolvers<any>();
	pending.set(++id, p.resolve);
	send({ jsonrpc: "2.0", id, method, params });
	return Promise.race([p.promise, Bun.sleep(60_000).then(() => ({ timeout: method }))]);
};
const init = await req("initialize", { protocolVersion: 2, clientCapabilities: {}, info: { name: "qa", version: "1" } });
if (init.timeout) console.log("TIMEOUT initialize");
const created = await req("session/new", { cwd: "/tmp/acp-v2-qa-project", mcpServers: [] });
if (created.timeout) console.log("TIMEOUT session/new");
else {
	const r = await req("session/prompt", { sessionId: created.result.sessionId, prompt: [{ type: "text", text: "Say ok." }] });
	if (r.timeout) console.log("TIMEOUT prompt");
	await Bun.sleep(20_000);
}
proc.kill();
process.exit(0);

