		const init = await c.request("initialize", { protocolVersion: 2, clientCapabilities: {}, info: { name: "qa", version: "1" } });
		check("initialize protocolVersion", init.result?.protocolVersion === (v2 ? 2 : 1), init.result?.protocolVersion);
		if (scenario === "v2-resume") {
			const { sessionId, userIds } = await Bun.file(sessionFile).json();
			const before = c.log.length;
			const resumed = await c.request("session/resume", { sessionId, cwd: project, replayFrom: { type: "start" } });
			const replayIds = c.updates("user_message").filter(l => l.i > before && l.i < resumed.i).map(l => l.frame.params.update.messageId);
			check("replayed user ids equal live ids", JSON.stringify(replayIds) === JSON.stringify(userIds), { replayIds, userIds });
			const snap = c.states().filter(s => s.i > before && s.i < resumed.i);
			check("state snapshot before resume response", snap.length > 0 && snap.at(-1)!.i < resumed.i, snap);
