type Frame = Record<string, unknown> & { id?: number | string; method?: string; params?: any; result?: any; error?: any };
type Logged = { i: number; t: number; dir: "→agent" | "←agent"; frame: Frame; issues?: string[] };
/** A response frame plus its position in the transcript, for ordering checks. */
type Reply = Frame & { i: number };

class Client {
	log: Logged[] = [];
	#proc: ReturnType<typeof Bun.spawn>;
	#next = 1;
	#pending = new Map<number, { method: string; resolve: (f: Reply) => void }>();
	#waiters: Array<{ pred: (l: Logged) => boolean; resolve: (l: Logged) => void }> = [];
	#t0 = Date.now();
	v2: boolean;
	violations: string[] = [];

	constructor(configFile: string, cwd: string, v2: boolean) {
		this.v2 = v2;
		this.#proc = Bun.spawn(["bun", CLI, "acp", "--config", configFile, "--model", MODEL], {
			cwd,
			stdin: "pipe",
			stdout: "pipe",
			stderr: "ignore",
		});
		void this.#read();
	}

	async #read(): Promise<void> {
		const reader = (this.#proc.stdout as ReadableStream<Uint8Array>).getReader();
		const dec = new TextDecoder();
		let buf = "";
		for (;;) {
			const { value, done } = await reader.read();
			if (done) return;
			buf += dec.decode(value, { stream: true });
			let nl: number;
			while ((nl = buf.indexOf("\n")) >= 0) {
				const line = buf.slice(0, nl).trim();
				buf = buf.slice(nl + 1);
				if (line) this.#onFrame(JSON.parse(line));
			}
		}
	}

	#record(dir: Logged["dir"], frame: Frame, issues?: string[]): Logged {
		const entry: Logged = { i: this.log.length, t: Date.now() - this.#t0, dir, frame, ...(issues?.length ? { issues } : {}) };
		this.log.push(entry);
		if (process.env.QA_TRACE) console.error(entry.t, dir, String(frame.method ?? `resp ${frame.id}`), frame.params?.update?.sessionUpdate ?? "", frame.params?.update?.state ?? "");
		for (const w of [...this.#waiters]) {
			if (w.pred(entry)) {
				this.#waiters.splice(this.#waiters.indexOf(w), 1);
				w.resolve(entry);
			}
		}
		return entry;
	}

