				const before = c.log.length;
				const instruction =
					scenario === "v2-wake"
						? "Start a background job with the bash tool (set async: true) running exactly `sleep 6 && echo wake-done`. Do not wait for it; reply only 'started' and end your turn."
						: "Use the task tool to spawn exactly one subagent (agent: sonic) whose task is: 'Run `sleep 5` with bash, then reply with the word pong.' Do not wait for its result; reply only 'spawned' and end your turn.";
				const resp = await c.request("session/prompt", { sessionId, prompt: text(instruction) });
				check("prompt acknowledged", typeof resp.result?.messageId === "string", resp.result ?? resp.error);
				const firstIdle = await c.waitFor(idleAfter(before), 90_000, "first idle");
				const wakeRunning = await c.waitFor(
					l => l.i > firstIdle.i && l.frame.params?.update?.sessionUpdate === "state_update" && l.frame.params.update.state === "running",
					90_000,
					"wake running",
				);
				const wakeIdle = await c.waitFor(idleAfter(wakeRunning.i), 90_000, "wake idle");
				const between = c.log.filter(l => l.i > firstIdle.i && l.i < wakeRunning.i && l.frame.params?.update?.sessionUpdate === "agent_message_chunk");
				check("no wake content before its running", between.length === 0, between.length);
				const wakeChunks = c.updates().filter(l => l.i > wakeRunning.i && l.i < wakeIdle.i);
				check("wake: running → updates → idle with no prompt open", wakeChunks.length > 0, { running: wakeRunning.i, idle: wakeIdle.i, stopReason: wakeIdle.frame.params.update.stopReason, updates: wakeChunks.length });
			} else if (scenario === "v2-cancel") {
				const before = c.log.length;
				const resp = c.request("session/prompt", { sessionId, prompt: text("Count from 1 to 400, one number per line, no other text.") });
				await c.waitFor(l => l.i > before && l.frame.params?.update?.sessionUpdate === "agent_message_chunk", 90_000, "first chunk");
				c.notify("session/cancel", { sessionId });
				const r = await resp;
				check("prompt answered (inserted before cancel → success)", !!r.result || r.error?.code === -32800, r.result ?? r.error);
				const idle = await c.waitFor(idleAfter(before), 30_000, "cancel idle");
				check("idle(cancelled)", idle.frame.params.update.stopReason === "cancelled", idle.frame.params.update);
				await Bun.sleep(1500);
				const after = c.log.filter(l => l.i > idle.i && l.dir === "←agent" && l.frame.params?.update?.sessionUpdate !== "usage_update");
				check("idle(cancelled) is the last content frame", after.every(l => l.frame.params?.update?.sessionUpdate !== "agent_message_chunk"), after.map(l => l.frame.params?.update?.sessionUpdate ?? l.frame.method));
			}
		}
	} catch (error) {
		check("scenario completed", false, String(error));
	} finally {
		await c.close();
	}
	check("no fs/terminal client calls and no schema issues", c.violations.length === 0, c.violations);
	const pass = checks.every(x => x.ok);
	const out = { scenario, model: MODEL, pass, checks, frames: c.log };
	await Bun.write(path.join(outDir, `${scenario}.json`), JSON.stringify(out, null, 1));
	console.log(`${scenario}: ${pass ? "PASS" : "FAIL"}`);
	for (const x of checks) console.log(`  ${x.ok ? "ok  " : "FAIL"} ${x.check}${x.ok ? "" : ` ${JSON.stringify(x.detail)?.slice(0, 400)}`}`);
	process.exit(pass ? 0 : 1);
}

await main();

